example_solution:
#[derive(Drop)]
pub struct User {
    name: ByteArray,
    age: u32,
    weight: u32,
}

pub trait UserTrait {
    fn new(name: ByteArray, age: u32, weight: u32) -> User;
    fn name(self: @User) -> @ByteArray;
    fn age(self: @User) -> u32;
    fn weight(self: @User) -> u32;
    fn set_age(ref self: User, new_age: u32);
    fn set_weight(ref self: User, new_weight: u32);
}

impl UserImpl of UserTrait {
    fn new(name: ByteArray, age: u32, weight: u32) -> User {
        User { name, age, weight }
    }

    fn name(self: @User) -> @ByteArray {
        self.name
    }

    fn age(self: @User) -> u32 {
        *self.age
    }

    fn weight(self: @User) -> u32 {
        *self.weight
    }

    fn set_age(ref self: User, new_age: u32) {
        self.age = new_age;
    }

    fn set_weight(ref self: User, new_weight: u32) {
        self.weight = new_weight;
    }
}

test_code:
use health_statistics::*;

const AGE: u32 = 89;
const WEIGHT: u32 = 131;

#[test]
fn name() {
    let name = "John";
    let user = UserTrait::new(name.clone(), AGE, WEIGHT);
    assert_eq!(user.name(), @name);
}

#[test]
#[ignore]
fn age() {
    let user = UserTrait::new("John", AGE, WEIGHT);
    assert_eq!(user.age(), AGE);
}

#[test]
#[ignore]
fn weight() {
    let user = UserTrait::new("John", AGE, WEIGHT);
    assert_eq!(user.weight(), WEIGHT);
}

#[test]
#[ignore]
fn set_age() {
    let new_age: u32 = 90;
    let mut user = UserTrait::new("John", AGE, WEIGHT);
    user.set_age(new_age);
    assert_eq!(user.age(), new_age);
}

#[test]
#[ignore]
fn set_weight() {
    let new_weight: u32 = 129;
    let mut user = UserTrait::new("John", AGE, WEIGHT);
    user.set_weight(new_weight);
    assert_eq!(user.weight(), new_weight);
}
